import json

# 1. Define custom tools
def get_weather(location):
    if "london" in location.lower():
        return "15C, Rain"
    return "22C, Sunny"

TOOLS = {'get_weather': get_weather}

# 2. ReAct Agent Engine Loop
def run_react_agent(user_goal, llm_client):
    chat_history = [
        {'role': 'system', 'content': 'You are an agent. Solve goals using tools. Format Action: {"name": "name", "args": "arg"}. Wait for Observation.'},
        {'role': 'user', 'content': user_goal}
    ]

    for step in range(5):
        print(f"[Step {step}] Querying Agent...")
        response = llm_client.chat(chat_history)
        print(f"[Agent Thought/Action]: {response}")

        if "Action:" in response:
            # Parse tool name and arguments
            action_json = response.split("Action:")[1].strip()
            action = json.loads(action_json)

            # Execute tool
            tool_fn = TOOLS.get(action['name'])
            observation = tool_fn(action['args'])
            print(f"[Tool Observation]: {observation}")

            chat_history.append({'role': 'assistant', 'content': response})
            chat_history.append({'role': 'user', 'content': f"Observation: {observation}"})
        else:
            print("[Agent finished with answer]:", response)
            break

