const http = require('http');
const { spawn } = require('child_process');

// Node.js server streaming LLM tokens using server-sent events
http.createServer(async (req, res) => {
    if (req.url === '/stream' && req.method === 'POST') {
        res.writeHead(200, {
            'Content-Type': 'text/event-stream',
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive'
        });

        // Mock calling local llama.cpp or vLLM process
        const modelProcess = spawn('python', ['-c', "import time; [print(f'data: token_{i}\n\n', flush=True) or time.sleep(0.05) for i in range(20)]"]);

        modelProcess.stdout.on('data', (data) => {
            res.write(data.toString());
        });

        modelProcess.on('close', () => {
            res.write('data: [DONE]\n\n');
            res.end();
        });
    } else {
        res.writeHead(404);
        res.end();
    }
}).listen(8080);
