import subprocess
import os

class SandboxRunner:
    def __init__(self, workspace_path='/tmp/sandbox_workspace'):
        self.workspace = workspace_path
        os.makedirs(self.workspace, exist_ok=True)

    def write_file(self, filename, code_content):
        file_path = os.path.join(self.workspace, filename)
        with open(file_path, 'w') as f:
            f.write(code_content)
        return f"File written to {file_path}"

    def execute_test(self, test_command):
        # Run command inside workspace with timeout limits
        try:
            result = subprocess.run(
                test_command,
                shell=True,
                cwd=self.workspace,
                capture_output=True,
                text=True,
                timeout=10
            )
            return {
                'exit_code': result.returncode,
                'stdout': result.stdout,
                'stderr': result.stderr
            }
        except subprocess.TimeoutExpired:
            return {'exit_code': -1, 'stdout': '', 'stderr': 'Timeout expired after 10s'}

# Example Usage
sandbox = SandboxRunner()
sandbox.write_file('test_app.py', 'def test_fn(): assert True')
print(sandbox.execute_test('python -m pytest test_app.py'))
